import{_ as e,o as r,c as n,a5 as o}from"./chunks/framework.DJo0M80U.js";const S=JSON.parse('{"title":"Sentry 是什么","description":"Sentry 是什么 Sentry 是一个 开源（BSL 1.1 许可） 的实时错误跟踪与性能监控平台，帮助开发者在生产环境中快速定位并修复崩溃、慢请求等问题，同时提供对应用端到端性能的可观测性。官方 SaaS 部署在 sentry.io，也可自建（Docker‑Compose。","frontmatter":{"title":"Sentry 是什么","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"Sentry 是什么 Sentry 是一个 开源（BSL 1.1 许可） 的实时错误跟踪与性能监控平台，帮助开发者在生产环境中快速定位并修复崩溃、慢请求等问题，同时提供对应用端到端性能的可观测性。官方 SaaS 部署在 sentry.io，也可自建（Docker‑Compose。","sidebarWeight":9,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/安全/Sentry 是什么.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/Sentry 是什么.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/Sentry 是什么.md"}'),s={name:"posts/Vue系统教程/06-工程化、质量与性能/Sentry 是什么.md"};function a(d,t,i,g,p,l){return r(),n("div",null,[...t[0]||(t[0]=[o('<div><h1 id="sentry-是什么" tabindex="-1">Sentry 是什么 <a class="header-anchor" href="#sentry-是什么" aria-label="Permalink to &quot;Sentry 是什么&quot;">​</a></h1><blockquote><p>本节目标：理解“Sentry 是什么”的核心思路，并能把它用于实际开发或面试表达。 <strong>Sentry 是什么</strong> Sentry 是一个 <strong>开源（BSL 1.1 许可）</strong> 的实时错误跟踪与性能监控平台，帮助开发者在生产环境中快速定位并修复崩溃、慢请求等问题，同时提供对应用端到端性能的可观测性。官方 SaaS 部署在 sentry.io，也可自建（Docker‑Compose / Kubernetes）实例。citeturn7view0</p></blockquote><p><strong>核心功能一览</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>功能</strong></td><td><strong>说明</strong></td><td><strong>适用语言/框架</strong></td></tr><tr><td><strong>Issue Tracking</strong></td><td>自动去重、按异常类型聚类，展示完整 stack trace、breadcrumbs 与用户设备信息</td><td>见下方官方 SDK 列表</td></tr><tr><td><strong>Alerts &amp; Notification</strong></td><td>阈值或规则触发的邮件 / Slack / PagerDuty 等告警</td><td>全栈</td></tr><tr><td><strong>Performance Monitoring (APM)</strong></td><td>追踪事务 (transactions) 和跨度 (spans)，可视化慢查询、N+1、外部调用瓶颈</td><td>JS / Python / Java / Go 等</td></tr><tr><td><strong>Profiling</strong></td><td>采样 CPU/内存火焰图，找出热函数</td><td>Python、Node、Java 等</td></tr><tr><td><strong>Release Health &amp; Code Mapping</strong></td><td>版本发布跟踪、自动关联 suspect commit / PR</td><td>GitHub、GitLab 等</td></tr><tr><td><strong>Session Replay</strong></td><td>回放用户会话（点击、网络、Console、Canvas 等），定位“看得见却复现不了”的问题；现已支持 Web＋移动端 React‑Native/Android/iOS</td><td>Web SDK ≥ 7.59；移动端 Open Betaciteturn9search0turn9search2</td></tr></tbody></table><p><strong>官方 SDK 覆盖</strong></p><ul><li><strong>前端</strong>：JavaScript（含 Vue / React / Angular）、Electron、React‑Native</li><li><strong>后端</strong>：Python、Django、Flask，Node/Express，Java/Kotlin，Go，Rust，PHP/Laravel…共 20 + 官方 SDK，可满足绝大多数技术栈citeturn7view0</li></ul><p><strong>与前端（Vue / Next.js）集成示例</strong> pnpm add @sentry/vue @sentry/tracing # Vue 3 // main.ts 或 entry.client.tsimport * as Sentry from &quot;@sentry/vue&quot;;import { BrowserTracing } from &quot;@sentry/tracing&quot;; Sentry.init({ app, dsn: &quot;<a href="https://%3Ckey%3E@sentry.io/%3Cproject%3E" target="_blank" rel="noreferrer">https://&lt;key&gt;@sentry.io/&lt;project&gt;</a>&quot;, integrations: [new BrowserTracing()], tracesSampleRate: 0.2, // APM 采样率 replaysSessionSampleRate: 0.1, // Replay 采样率 replaysOnErrorSampleRate: 1.0 // 出错时必录}); Next.js 14（App Router）可使用 @sentry/nextjs，同时在 middleware.ts 添加 Sentry.wrapApiHandler* / wrapServerComponent* 以捕获服务端异常。</p><p><strong>自建 vs SaaS</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>方案</strong></td><td><strong>亮点</strong></td><td><strong>注意事项</strong></td></tr><tr><td><strong>SaaS</strong> (sentry.io)</td><td>5 分钟开箱、托管升级、内置多云存储</td><td>免费额度(5k events/月)，超量计费</td></tr><tr><td><strong>Self</strong>**‑**<strong>Hosted</strong></td><td>数据完全自持、无限事件量</td><td>需要 Postgres + ClickHouse + Kafka（Docker Compose 一键部署）；升级需跟随官方 release 节奏</td></tr></tbody></table><p>最新版 25.4.0（2025‑04‑15）中改进了 Java 自动代码映射、Issue 列表滚动表现等细节citeturn1view0。</p><p><strong>适合你的场景？</strong></p><ul><li><strong>多端产品</strong>：前后端一个平台统一可观测，省去分散日志方案</li><li><strong>快速迭代</strong>：实时发现致命错误，配合 Git commit 自动定位责任代码</li><li><strong>性能敏感</strong>：APM + Profiling 找到慢事务和 CPU 热点</li><li><strong>用户体验</strong>：Session Replay 让“客服无法复现”的问题只需点开录像</li></ul><p>如果你正维护 Vue / Next.js 项目，Sentry 几乎是部署成本最低、社区最活跃的一站式监控方案之一。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/680773ed-ddf4-8004-a547-5f2b201cc436" target="_blank" rel="noreferrer">https://chatgpt.com/c/680773ed-ddf4-8004-a547-5f2b201cc436</a>&gt;</p></div>',1)])])}const u=e(s,[["render",a]]);export{S as __pageData,u as default};
